import {bindConnectedApps} from './book-connected.js?v=5.33.0';
import {APP_COPY,appChapter,appSection} from './shared/book-apps.js?v=5.33.0';
import {BOOK_PARTS,EDITORIAL_COPY,orderedChapters,capabilityTable} from './shared/book-editorial.js?v=5.33.0';
import {integratedDemoShell,bindIntegratedDemo,INTEGRATED_COPY} from './integrated-demo.js?v=5.33.0';
import {shopSetupShell,bindShopSetup} from './shop-setup.js?v=5.33.0';
import {ownerJourneyShell,bindOwnerJourney} from './owner-journey.js?v=5.33.0';
import {teamBook} from './team.js?v=5.33.0';
import {showcaseShell,bindShowcase} from './showcase.js?v=5.33.0';
import {ramiChapters,ramiSection,bindRami} from './rami-book.js?v=5.33.0';
import {ORDER_COPY} from './shared/order-copy.js?v=5.33.0';
import {brandLogo,brandMark} from './shared/brand.js?v=5.33.0';
import {VISUAL_COPY} from './shared/visual-copy.js?v=5.33.0';
import {BOOK} from './book-content.js?v=5.33.0';
import {CHAT_COPY} from './shared/conversation-copy.js?v=5.33.0';
import {UI} from './shared/copy.js?v=5.33.0';
import {esc,getLang,setLang,languageOptions,icon} from './shared/core.js?v=5.33.0';
let lang=getLang(),menuOpen=false,navCollapsed=false,active='cover';
const root=document.querySelector('#book'),mobile=matchMedia('(max-width:760px)'),reduceMotion=matchMedia('(prefers-reduced-motion:reduce)');
let motion=true;try{motion=localStorage.getItem('one-shop-motion')!=='off';}catch{}
const b=()=>BOOK[lang],t=k=>ORDER_COPY[lang]?.[k]||CHAT_COPY[lang]?.[k]||UI[lang][k]||k,w=k=>VISUAL_COPY[lang]?.[k]||VISUAL_COPY.en[k];
const art=name=>`assets/one-shop/stories/${name}.webp`;
const storyMap={why:'multilingual-table',onboarding:'owner-studio',qr:'table-qr',team:'service-desk',partnership:'connected-shops'};
const chapterArt=id=>storyMap[id]?art(storyMap[id]):`assets/one-shop/chapters/${id}.webp`;
let sceneObserver,disposeShowcase=()=>{},disposeOwnerJourney=()=>{},disposeShopSetup=()=>{},disposeIntegratedDemo=()=>{},disposeConnectedApps=()=>{};
const editorial=()=>EDITORIAL_COPY[lang];
const sections=()=>orderedChapters(b(),ramiChapters(lang),[appChapter(lang)]);
const chapterIds=()=>['cover',...sections().map(s=>s.id)];
const groups=BOOK_PARTS;
function navLink(id,title,ic){return `<a href="#${id}" data-chapter="${id}" data-search-link>${icon(ic)}<span>${esc(title)}</span><i class="read-dot" aria-hidden="true"></i></a>`;}
function navigation(){const e=editorial(),all=sections();return `<aside class="book-nav ${menuOpen?'open':''}" id="book-nav" aria-label="${esc(b().contents)}"><div class="nav-heading"><span>${esc(w('bookTitle'))}</span><button class="icon-button nav-close" id="nav-close" aria-label="${esc(t('close'))}">${icon('close')}</button></div><label class="nav-search">${icon('search')}<input id="chapter-search" type="search" placeholder="${esc(w('search'))}" aria-label="${esc(w('search'))}" autocomplete="off"></label><nav class="nav-scroll" aria-label="${esc(b().contents)}">${navLink('cover',b().title,'spark')}<a class="show-nav-link nav-primary" href="#integrated-demo" data-search-link>${icon('chat')}<span>${esc(e.start)}</span></a>${groups.map((group,i)=>`<details class="nav-group ${group.key==='brand'?'nav-rami':''}" ${i===0?'open':''}><summary><b>${String(i+1).padStart(2,'0')}</b>${esc(e.groups[i])}<span aria-hidden="true">⌄</span></summary>${group.ids.map(id=>all.find(s=>s.id===id)).map(chapter=>navLink(chapter.id,chapter.id==='faq'?e.scope:chapter.title,({apps:'dashboard',experience:'chat',onboarding:'profile',qr:'qr',team:'dashboard',operations:'orders'})[chapter.id]||'menu')).join('')}</details>`).join('')}<details class="nav-group nav-demo-group"><summary>${esc(INTEGRATED_COPY[lang].details)}<span aria-hidden="true">⌄</span></summary><a href="#live-demo" data-search-link>${esc(e.details[0])}</a><a href="#setup-demo" data-search-link>${esc(e.details[1])}</a><a href="#owner-demo" data-search-link>${esc(e.details[2])}</a></details><p class="nav-empty" id="nav-empty" hidden>${esc(w('noResults'))}</p></nav><div class="nav-bottom"><div class="nav-progress-label"><span>${esc(w('reading'))}</span><b id="nav-percent">0%</b></div><div class="nav-progress" role="progressbar" aria-label="${esc(w('reading'))}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i></i></div><div class="nav-demo-links apps-directory-link"><a href="#apps">${icon('dashboard')}${esc(APP_COPY[lang].nav)}</a></div><small>${esc(b().partner)}</small></div></aside>`;}

function render(){
 disposeConnectedApps();disposeShowcase();disposeOwnerJourney();disposeShopSetup();disposeIntegratedDemo();
 document.documentElement.lang=lang;document.title=`원샵 · one shop ai | ${w('bookTitle')} 5.33.0`;
 document.documentElement.dataset.motion=motion&&!reduceMotion.matches?'on':'off';
 document.documentElement.dataset.nav=navCollapsed?'closed':'open';
 root.innerHTML=`<a class="skip-link" href="#main">${esc(b().read)}</a><div class="reading-progress" id="progress"></div><header class="book-top"><button id="nav-toggle" class="icon-button" aria-label="${esc(b().contents)}" aria-controls="book-nav" aria-expanded="${mobile.matches?menuOpen:!navCollapsed}">${icon('menu')}</button><a class="platform" href="#cover">${brandLogo()}</a><span class="version">5.33.0</span><div class="book-tools"><button id="motion-toggle" class="icon-button motion-toggle" aria-label="${esc(w(motion?'motionPause':'motionPlay'))}" title="${esc(w(motion?'motionPause':'motionPlay'))}" aria-pressed="${motion}">${motion?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m8 4 12 8-12 8Z"/></svg>'}</button><select id="book-language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select><a class="top-guest" href="#apps">${esc(APP_COPY[lang].nav)}${icon('arrow')}</a><button class="icon-button" id="print-book" aria-label="${esc(b().print)}">${icon('orders')}</button></div></header><button id="nav-overlay" aria-label="${esc(t('close'))}" hidden></button>${navigation()}<main id="main" tabindex="-1"><section id="cover" class="cover chapter"><div class="cover-partner">${esc(b().partner)}<span>2026 · 5.33.0</span></div><div class="brand-type" aria-label="one shop ai"><span>one</span><span>shop<em>ai</em></span><i aria-hidden="true"></i></div><div class="hero-layout"><div class="hero-copy"><h1>${esc(editorial().headline).replace(/\n/g,'<br>')}</h1><p class="cover-intro">${esc(editorial().intro)}</p><div class="cover-actions"><a class="button primary" href="#integrated-demo">${esc(editorial().start)}${icon('arrow')}</a><a class="button secondary" href="#glance">${esc(editorial().read)}</a></div><p class="cover-demo-note">${esc(editorial().badge)} <a href="#faq">${esc(editorial().scope)}</a></p></div><div class="hero-scene"><img class="hero-neighborhood" src="${art('shop-neighborhood')}" alt="${esc(b().sections[0].title)}" width="1400" height="792" fetchpriority="high"><svg class="hero-path" viewBox="0 0 600 430" fill="none" aria-hidden="true"><path d="M80 350C30 140 550 420 525 130" pathLength="1"/><circle cx="525" cy="130" r="6"/></svg><div class="hero-mascot">${brandMark('greeting',true)}<span>${esc(w('greeting'))}</span></div><span class="scene-caption">${esc(w('artNote'))}</span></div></div><nav class="book-reading-path" aria-label="${esc(b().contents)}">${[0,1,3].map(index=>`<a href="#${groups[index].ids[0]}"><span>${esc(editorial().groups[index])}</span><b>${esc(sections().find(ch=>ch.id===groups[index].ids[0]).title)}</b>${icon('arrow')}</a>`).join('')}</nav></section>${sections().map((s,i)=>s.rami?ramiSection(s,lang,{number:i+1,partLabel:s.id==='rami'?editorial().groups[4]:''}):section(s,i)).join('')}<footer><a class="platform" href="#cover">${brandLogo()}</a><h2>${esc(b().subtitle)}</h2><p>${esc(b().partner)}</p><div class="cover-actions"><a href="#integrated-demo" class="button primary">${esc(editorial().start)}${icon('arrow')}</a><a class="button secondary" href="#workshop">${esc(b().sections.find(s=>s.id==='workshop').title)}</a></div></footer></main><div class="chapter-dock"><button id="previous-chapter" class="dock-direction" aria-label="${esc(w('previous'))}">${icon('arrow')}</button><a id="current-chapter" href="#cover"><small>${esc(w('chapter'))}</small><span>${esc(b().title)}</span></a><button id="next-chapter" class="dock-direction" aria-label="${esc(w('next'))}">${icon('arrow')}</button></div>`;
 bind();disposeConnectedApps=bindConnectedApps(document.querySelector('#apps'),lang);bindRami(lang);disposeShowcase=bindShowcase(document.querySelector('#live-demo'),lang);disposeOwnerJourney=bindOwnerJourney(document.querySelector('#owner-demo'),lang);disposeShopSetup=bindShopSetup(document.querySelector('#setup-demo'),lang);disposeIntegratedDemo=bindIntegratedDemo(document.querySelector('#integrated-demo'),lang);updateProgress();
 sceneObserver?.disconnect();sceneObserver=new IntersectionObserver(entries=>{for(const e of entries)e.target.classList.toggle('is-in-view',e.isIntersecting);},{threshold:.12});
 document.querySelectorAll('.chapter-spread,.hero-scene,.brand-type').forEach(el=>sceneObserver.observe(el));
}
function chapterVisual(s){return `<figure class="chapter-visual story-visual"><div class="scene-window"><img src="${chapterArt(s.id)}" alt="${esc(s.title)}" width="1400" height="792" loading="lazy" decoding="async"><svg class="scene-orbit" viewBox="0 0 700 396" fill="none" aria-hidden="true"><path d="M25 320C180 415 520 430 675 70" pathLength="1"/><circle cx="675" cy="70" r="6"/></svg></div><figcaption><span>${esc(s.title)}</span>${esc(w('artNote'))}</figcaption></figure>`;}
const disclosure=(label,content)=>`<details class="demo-disclosure"><summary>${esc(label)}<span aria-hidden="true">+</span></summary><div class="demo-disclosure-body">${content}</div></details>`;
function section(s,i){if(s.id==='apps')return appSection(lang,i+1);const e=editorial(),isDemo=s.id==='experience',part=groups.findIndex(p=>p.ids.includes(s.id)),first=groups[part].ids[0]===s.id;return `<section class="book-chapter chapter ${isDemo?'chapter-demo':i%3===1?'chapter-wide':i%3===2?'chapter-reverse':''}" id="${s.id}" aria-labelledby="heading-${s.id}">${first?`<p class="book-part-label">${esc(e.groups[part])}</p>`:''}<div class="chapter-head"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><p>${esc(s.id==='faq'?e.scope:s.title)}</p></div><div class="chapter-spread ${isDemo?'experience-copy':''}"><h2 id="heading-${s.id}">${esc(s.lead)}</h2>${isDemo?'':chapterVisual(s)}</div><div class="chapter-copy">${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div>${isDemo?`${integratedDemoShell()}${disclosure(e.details[0],showcaseShell())}`:''}${s.id==='onboarding'?`${disclosure(e.details[1],shopSetupShell())}${disclosure(e.details[2],ownerJourneyShell())}`:''}<ul class="principle-row">${s.points.map(x=>`<li>${icon('check')}<span>${esc(x)}</span></li>`).join('')}</ul>${extra(s.id)}</section>`;}

function extra(id){if(id==='experience')return '';
 if(id==='onboarding')return `<a class="owner-feature" href="jumo/owner.html?lang=${lang}#storeSetup"><div>${icon('profile')}<h3>${esc(t('storeSetup'))}</h3><p>${esc(t('storeName'))} · ${esc(t('upload'))} · QR</p></div><span class="round-arrow">${icon('arrow')}</span></a>`;
 if(id==='team')return `${teamBook(lang)}`;
 if(id==='journey')return `<div class="team-demo"><a href="jumo/?lang=${lang}#games">${icon('games')}<strong>${esc(t('games'))}</strong><span>${esc(t('gameNote'))}</span></a><a href="jumo/owner.html?lang=${lang}#dashboard">${icon('chat')}<strong>${esc(t('guestLog'))}</strong><span>${esc(t('detailsUse'))}</span></a></div>`;
 if(id==='architecture')return `<div class="architecture-diagram"><div>${esc(t('menu'))} / ${esc(t('chat'))}</div><span>↓</span><div class="architecture-center">원샵 · one shop ai<br><small>${esc(t('scopeNote'))} · ${esc(t('budgetTitle'))}</small></div><span>↓</span><div class="architecture-end"><b>${esc(t('storeAssistant'))}</b><b>POS</b><b>${esc(t('orderInbox'))}</b></div><p>${esc(t('notConnected'))} · ${esc(b().demoNote)}</p></div>`;
 if(id==='operations')return `<div class="steps">${['pending','accepted','preparing','ready','completed'].map(k=>`<span>${esc(t(k))}</span>`).join('<i>→</i>')}</div><a class="text-link" href="jumo/owner.html?lang=${lang}#orderInbox">${esc(t('orderInbox'))} ↗</a>`;
 if(id==='business')return `<a class="text-link" href="#growth">${esc(b().sections.find(s=>s.id==='growth').title)}${icon('arrow')}</a>`;
 if(id==='qr')return `<a class="button secondary" href="jumo/owner.html?lang=${lang}#storeSetup">${icon('qr')}${esc(t('qrTitle'))}</a>`;
 if(id==='faq')return `${capabilityTable(lang)}<p class="scope-language-note">${esc(b().translationNote)}</p><details class="book-references"><summary>${esc(b().sourceTitle)}</summary><div class="sources"><a href="https://isaacweb007.github.io/jumo-joseon-hiphop-book/?lang=ko#cover" target="_blank" rel="noopener">${esc(w("brandReference"))} ↗</a><a href="https://familywallet-book.vercel.app/#cover" target="_blank" rel="noopener">${esc(w("bookReference"))} ↗</a><a href="https://developers.openai.com/api/reference/responses/overview" target="_blank" rel="noopener">OpenAI Responses API ↗</a><a href="api/pos-contract.json" target="_blank" rel="noopener">${esc(t('apiContract'))} ↗</a></div></details>`;
 return '';}
function setMenu(open,focus=true){
 if(!mobile.matches){navCollapsed=!open;document.documentElement.dataset.nav=open?'open':'closed';document.querySelector('#nav-toggle').setAttribute('aria-expanded',String(open));return;}
 menuOpen=open;const nav=document.querySelector('#book-nav');nav.classList.toggle('open',open);nav.inert=!open;document.querySelector('#nav-overlay').hidden=!open;document.querySelector('#main').inert=open;document.querySelector('.chapter-dock').inert=open;document.querySelector('#nav-toggle').setAttribute('aria-expanded',String(open));document.body.classList.toggle('nav-modal',open);
 if(open){nav.setAttribute('role','dialog');nav.setAttribute('aria-modal','true');if(focus)document.querySelector('#chapter-search').focus();}else{nav.removeAttribute('role');nav.removeAttribute('aria-modal');if(focus)document.querySelector('#nav-toggle').focus();}
}
function filterNav(query){let found=0;const q=query.trim().toLocaleLowerCase();document.querySelectorAll('[data-search-link]').forEach(link=>{const chapter=sections().find(s=>s.id===link.dataset.chapter);const match=!q||[link.textContent,chapter?.lead||'',...(chapter?.points||[])].join(' ').toLocaleLowerCase().includes(q);link.hidden=!match;if(match)found++;});document.querySelectorAll('.nav-group').forEach(group=>{group.hidden=![...group.querySelectorAll('[data-search-link]')].some(a=>!a.hidden);if(q&&!group.hidden)group.open=true;else if(!q)group.open=!!group.querySelector(`[data-chapter="${active}"]`);});document.querySelector('#nav-empty').hidden=found>0;}
function revealAnchor(id=location.hash.slice(1)){const target=document.getElementById(id);if(!target)return;for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;requestAnimationFrame(()=>target.scrollIntoView({behavior:'instant',block:'start'}));}

function goChapter(delta){const ids=chapterIds(),target=ids[ids.indexOf(active)+delta];if(target)location.hash=target;}
function bind(){
 document.querySelector('#book-language').addEventListener('change',e=>{const anchor=['#owner-demo','#setup-demo','#live-demo','#integrated-demo'].includes(location.hash)?location.hash.slice(1):active;lang=e.target.value;setLang(lang);menuOpen=false;render();revealAnchor(anchor);});
 document.querySelector('#nav-toggle').addEventListener('click',()=>setMenu(mobile.matches?!menuOpen:navCollapsed));
 document.querySelector('#nav-close').addEventListener('click',()=>setMenu(false));document.querySelector('#nav-overlay').addEventListener('click',()=>setMenu(false));
 document.querySelector('#print-book').addEventListener('click',()=>window.print());
 document.querySelector('#chapter-search').addEventListener('input',e=>filterNav(e.target.value));
 document.querySelector('#book-nav').addEventListener('click',e=>{if(e.target.closest('a')&&mobile.matches)setMenu(false);});
 document.querySelector('#previous-chapter').addEventListener('click',()=>goChapter(-1));document.querySelector('#next-chapter').addEventListener('click',()=>goChapter(1));
 document.querySelector('#motion-toggle').addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('one-shop-motion',motion?'on':'off');}catch{}document.documentElement.dataset.motion=motion&&!reduceMotion.matches?'on':'off';const btn=document.querySelector('#motion-toggle');btn.setAttribute('aria-pressed',String(motion));btn.setAttribute('aria-label',w(motion?'motionPause':'motionPlay'));btn.title=w(motion?'motionPause':'motionPlay');btn.innerHTML=motion?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m8 4 12 8-12 8Z"/></svg>';});
 document.querySelectorAll('.demo-disclosure').forEach(detail=>detail.addEventListener('toggle',()=>{if(!detail.open)document.dispatchEvent(new CustomEvent('one-shop-demo-play',{detail:'closed'}));requestAnimationFrame(updateProgress);}));
 if(mobile.matches)setMenu(false,false);
}
let scheduled=false;
function updateProgress(){
 document.documentElement.dataset.readingDemo=String([...document.querySelectorAll('.book-showcase')].some(el=>el.getClientRects().length&&el.getBoundingClientRect().top<innerHeight*.75&&el.getBoundingClientRect().bottom>160));
 const total=document.documentElement.scrollHeight-innerHeight,percent=Math.max(0,Math.min(100,Math.round(total?scrollY/total*100:0)));
 document.querySelector('#progress').style.width=percent+'%';document.querySelector('#nav-percent').textContent=percent+'%';document.querySelector('.nav-progress').setAttribute('aria-valuenow',percent);document.querySelector('.nav-progress i').style.width=percent+'%';
 let nextActive='cover';document.querySelectorAll('.chapter').forEach(x=>{if(x.getBoundingClientRect().top<200)nextActive=x.id;});const changed=active!==nextActive;active=nextActive;
 const ids=chapterIds(),index=ids.indexOf(active);
 document.querySelectorAll('[data-chapter]').forEach(x=>{const selected=x.dataset.chapter===active;x.classList.toggle('active',selected);x.classList.toggle('is-read',ids.indexOf(x.dataset.chapter)<index);if(selected)x.setAttribute('aria-current','location');else x.removeAttribute('aria-current');});
 if(changed){const link=document.querySelector('[data-chapter="'+active+'"]'),nav=document.querySelector('.nav-scroll');if(link&&nav){const group=link.closest('details');if(group)group.open=true;const n=nav.getBoundingClientRect(),g=group?.getBoundingClientRect(),a=g&&g.height<=n.height?g:link.getBoundingClientRect();if(a.top<n.top)nav.scrollTop-=n.top-a.top+12;else if(a.bottom>n.bottom)nav.scrollTop+=a.bottom-n.bottom+12;}}
 document.querySelector('#previous-chapter').disabled=index<=0;document.querySelector('#next-chapter').disabled=index===ids.length-1;const current=document.querySelector('#current-chapter');current.href='#'+active;current.querySelector('span').textContent=sections().find(s=>s.id===active)?.title||b().title;scheduled=false;
}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateProgress);}},{passive:true});
addEventListener('resize',()=>requestAnimationFrame(updateProgress),{passive:true});
addEventListener('keydown',e=>{if(e.key==='Escape'&&menuOpen)setMenu(false);if(e.key==='Tab'&&menuOpen&&mobile.matches){const focusable=[...document.querySelector('#book-nav').querySelectorAll('a,button,input,summary')].filter(x=>!x.closest('[hidden]')&&x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
mobile.addEventListener('change',()=>{menuOpen=false;document.body.classList.remove('nav-modal');render();});
reduceMotion.addEventListener('change',()=>document.documentElement.dataset.motion=motion&&!reduceMotion.matches?'on':'off');
render();
// Deep links also reveal optional demonstrations without resetting their state.
addEventListener('hashchange',()=>revealAnchor());
let printDetails=[];addEventListener('beforeprint',()=>{printDetails=[...document.querySelectorAll('details.demo-disclosure:not([open])')];printDetails.forEach(el=>el.open=true);});addEventListener('afterprint',()=>{printDetails.forEach(el=>el.open=false);printDetails=[];});
revealAnchor();
